-- DECIDE9JA: Complete LGA → Representative Mapping
-- Generated from lga_mapping_data.json
-- Total states: 37
-- Total LGAs: 774
-- Adapted for PostgreSQL

-- Create table if not exists
CREATE TABLE IF NOT EXISTS lga_representatives (
    id SERIAL PRIMARY KEY,
    state VARCHAR(50) NOT NULL,
    lga VARCHAR(100) NOT NULL,
    senatorial_district VARCHAR(100),
    governor_name VARCHAR(100),
    governor_party VARCHAR(20),
    senator_name VARCHAR(100),
    senator_party VARCHAR(20),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(state, lga)
);

CREATE INDEX IF NOT EXISTS idx_lga_reps_state ON lga_representatives(state);
CREATE INDEX IF NOT EXISTS idx_lga_reps_state_lga ON lga_representatives(state, lga);

-- Clear existing data
DELETE FROM lga_representatives;

